function groupName(groups, groupId) {
  return groups.find((g) => g.id === groupId)?.name || "—";
}

// A place (first/second/third) can hold 1 or 2 co-winning participants.
// This normalizes older single-object data into the array shape used everywhere below.
function placeEntries(value) {
  if (!value) return [];
  return Array.isArray(value) ? value.filter(Boolean) : [value];
}

// Sums each group's points across every published competition result.
// If two co-winners at the same place are from different groups, both groups
// are credited; if they're from the same group, that group is only credited once.
function computeGroupTotals(groups, results) {
  const totals = groups.map((g) => ({ ...g, total: 0 }));
  const byId = Object.fromEntries(totals.map((t) => [t.id, t]));
  Object.values(results).forEach((r) => {
    if (!r.published) return;
    ["first", "second", "third"].forEach((place) => {
      const creditedGroups = new Set();
      placeEntries(r[place]).forEach((entry) => {
        if (entry?.groupId) creditedGroups.add(entry.groupId);
      });
      creditedGroups.forEach((groupId) => {
        if (byId[groupId]) byId[groupId].total += PLACE_POINTS[place];
      });
    });
  });
  return totals;
}

function topThreeGroups(totals) {
  return [...totals].sort((a, b) => b.total - a.total).slice(0, 3);
}

