function findStudentById(students, studentId) {
  return students.find((s) => s.studentId === studentId);
}

// Finds every published competition a given student ID placed in
function findStudentResultsById(studentId, competitions, results) {
  if (!studentId) return [];
  const rows = [];
  Object.entries(results).forEach(([compId, r]) => {
    if (!r.published) return;
    ["first", "second", "third"].forEach((place) => {
      const matched = placeEntries(r[place]).some((e) => e?.studentId?.toLowerCase() === studentId.toLowerCase());
      if (matched) {
        const comp = competitions.find((c) => c.id === compId);
        if (comp) {
          rows.push({
            competitionName: comp.name,
            place,
            medal: place === "first" ? "🥇" : place === "second" ? "🥈" : "🥉",
          });
        }
      }
    });
  });
  return rows;
}

