// Poster template themes, inspired by the school's own poster designs
const POSTER_THEMES = [
  { key: "emerald", label: "Emerald Gold", bgTop: "#0b2e22", bgBottom: "#123f2f", cardFill: "#0f3a2c", cardStroke: "#D4AF37", badgeFill: "#0f3a2c", badgeStroke: "#D4AF37", badgeText: "#D4AF37", numberBg: "#0f3a2c", numberText: "#D4AF37", pillFill: "#f4ead2", nameText: "#12261d", idText: "#5a6b60", headerText: "#D4AF37", subText: "rgba(244,234,210,0.75)" },
  { key: "cream", label: "Cream Gold", bgTop: "#f6efe0", bgBottom: "#efe4cc", cardFill: "#faf6ec", cardStroke: "#c9a227", badgeFill: "#123f2f", badgeStroke: "#c9a227", badgeText: "#f4ead2", numberBg: "#123f2f", numberText: "#f4ead2", pillFill: "#ffffff", nameText: "#16211c", idText: "#6b7a70", headerText: "#123f2f", subText: "#8a7a4a" },
  { key: "sky", label: "Sky Rose", bgTop: "#eaf2fb", bgBottom: "#fdeef4", cardFill: "#ffffff", cardStroke: "#c9a227", badgeFill: "#123f2f", badgeStroke: "#c9a227", badgeText: "#f4ead2", numberBg: "#123f2f", numberText: "#f4ead2", pillFill: "#f7f8fb", nameText: "#16211c", idText: "#6b7a8a", headerText: "#123f2f", subText: "#8a8fa0" },
  { key: "ocean", label: "Ocean Ivory", bgTop: "#0e3b52", bgBottom: "#e8dfc8", cardFill: "#faf6ec", cardStroke: "#c9a227", badgeFill: "#123f2f", badgeStroke: "#c9a227", badgeText: "#f4ead2", numberBg: "#123f2f", numberText: "#f4ead2", pillFill: "#ffffff", nameText: "#16211c", idText: "#6b7a70", headerText: "#123f2f", subText: "#3a5568" },
];

function drawRoundedRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

function PosterGenerator({ competition, result, students, onSaveToGallery }) {
  const [open, setOpen] = useState(false);
  const [theme, setTheme] = useState(POSTER_THEMES[0].key);
  const canvasRef = useRef(null);

  useEffect(() => {
    if (!open || !canvasRef.current) return;
    drawPoster(canvasRef.current, competition, result, students, theme);
  }, [open, theme, competition, result, students]);

  function handleSave() {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const dataUrl = canvas.toDataURL("image/png");
    const a = document.createElement("a");
    a.href = dataUrl;
    a.download = `${competition.name.replace(/\s+/g, "-")}-${theme}-poster.png`;
    a.click();
    onSaveToGallery({ id: newId(), dataUrl, competitionName: competition.name, style: theme, createdAt: Date.now() });
  }

  return (
    <div className="mt-8">
      {!open ? (
        <button onClick={() => setOpen(true)} className="rounded-full bg-emerald-700 px-5 py-2.5 text-sm font-semibold text-white hover:bg-emerald-800">🖼️ Generate Poster</button>
      ) : (
        <div className="rounded-2xl border border-emerald-900/10 bg-white/90 p-6">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <h3 className="font-display text-lg text-emerald-900">Poster Preview</h3>
            <div className="flex flex-wrap gap-2">
              {POSTER_THEMES.map((t) => (
                <button key={t.key} onClick={() => setTheme(t.key)} className={`rounded-full px-4 py-1.5 text-xs font-semibold ${theme === t.key ? "bg-emerald-700 text-white" : "border border-emerald-900/10 text-emerald-900/70"}`}>
                  {t.label}
                </button>
              ))}
            </div>
          </div>
          <div className="mt-4 flex justify-center overflow-x-auto">
            <canvas ref={canvasRef} width={800} height={1000} className="max-w-full rounded-xl border border-emerald-900/10 shadow-md" style={{ width: "320px", height: "400px" }} />
          </div>
          <div className="mt-4 flex flex-wrap justify-center gap-2">
            <button onClick={handleSave} className="rounded-full bg-yellow-500 px-5 py-2.5 text-sm font-semibold text-emerald-900 hover:bg-yellow-400">💾 Save to Gallery</button>
            <button onClick={() => setOpen(false)} className="rounded-full border border-emerald-900/15 px-5 py-2.5 text-sm font-semibold text-emerald-900/70">Close</button>
          </div>
        </div>
      )}
    </div>
  );
}

function drawPoster(canvas, competition, result, students, themeKey) {
  const theme = POSTER_THEMES.find((t) => t.key === themeKey) || POSTER_THEMES[0];
  const ctx = canvas.getContext("2d");
  const W = canvas.width, H = canvas.height;

  const bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, theme.bgTop);
  bg.addColorStop(1, theme.bgBottom);
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // Arch-shaped card, echoing the mosque-arch silhouette used in the school's own posters
  const cardX = 70, cardY = 50, cardW = W - 140, cardH = H - 110;
  const archRadius = cardW / 2;
  ctx.beginPath();
  ctx.moveTo(cardX, cardY + archRadius);
  ctx.arc(cardX + archRadius, cardY + archRadius, archRadius, Math.PI, 0, false);
  ctx.lineTo(cardX + cardW, cardY + cardH - 30);
  ctx.quadraticCurveTo(cardX + cardW, cardY + cardH, cardX + cardW - 30, cardY + cardH);
  ctx.lineTo(cardX + 30, cardY + cardH);
  ctx.quadraticCurveTo(cardX, cardY + cardH, cardX, cardY + cardH - 30);
  ctx.closePath();
  ctx.fillStyle = theme.cardFill;
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = theme.cardStroke;
  ctx.stroke();

  ctx.textAlign = "center";

  ctx.font = "44px serif";
  ctx.fillStyle = theme.headerText;
  ctx.fillText("🕌", W / 2, cardY + 70);

  ctx.font = "700 20px sans-serif";
  ctx.fillStyle = theme.headerText;
  ctx.fillText("SIRAJUL HUDA ARABIC SCHOOL", W / 2, cardY + 110);

  ctx.font = "400 14px sans-serif";
  ctx.fillStyle = theme.subText;
  ctx.fillText("لوها  ·  WAVES OF LOVE", W / 2, cardY + 135);

  // RESULT badge
  const badgeW = 200, badgeH = 46, badgeX = W / 2 - badgeW / 2, badgeY = cardY + 160;
  drawRoundedRect(ctx, badgeX, badgeY, badgeW, badgeH, 23);
  ctx.fillStyle = theme.badgeFill;
  ctx.fill();
  ctx.lineWidth = 2;
  ctx.strokeStyle = theme.badgeStroke;
  ctx.stroke();
  ctx.font = "700 24px sans-serif";
  ctx.fillStyle = theme.badgeText;
  ctx.fillText("RESULT", W / 2, badgeY + 31);

  // Competition name
  ctx.font = "700 26px serif";
  ctx.fillStyle = theme.nameText;
  wrapText(ctx, competition.name, W / 2, badgeY + 90, cardW - 120, 32);

  // Numbered rows: 01 / 02 / 03, auto-filled from the announced result
  const places = [
    { key: "first", num: "01" },
    { key: "second", num: "02" },
    { key: "third", num: "03" },
  ];
  const rowY0 = badgeY + 220;
  const rowGap = 130;
  const rowX = cardX + 50;
  const rowW = cardW - 100;
  const rowH = 72;

  places.forEach((p, i) => {
    const winners = placeEntries(result[p.key]).map((entry) => ({
      entry,
      student: findStudentById(students, entry?.studentId),
    }));
    const nameText = winners.length ? winners.map((w) => w.student?.name || "—").join(" & ") : "Result pending";
    const idText = winners.length ? winners.map((w) => w.entry?.studentId || "—").join(", ") : "—";
    const y = rowY0 + i * rowGap;

    drawRoundedRect(ctx, rowX, y, 64, rowH, 16);
    ctx.fillStyle = theme.numberBg;
    ctx.fill();
    ctx.textAlign = "center";
    ctx.font = "700 22px sans-serif";
    ctx.fillStyle = theme.numberText;
    ctx.fillText(p.num, rowX + 32, y + rowH / 2 + 8);

    const pillX = rowX + 80;
    const pillW = rowW - 80;
    drawRoundedRect(ctx, pillX, y, pillW, rowH, rowH / 2);
    ctx.fillStyle = theme.pillFill;
    ctx.fill();
    ctx.strokeStyle = "rgba(0,0,0,0.08)";
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.textAlign = "left";
    ctx.font = winners.length > 1 ? "700 17px sans-serif" : "700 22px sans-serif";
    ctx.fillStyle = theme.nameText;
    ctx.fillText(nameText, pillX + 26, y + 30);
    ctx.font = "400 14px sans-serif";
    ctx.fillStyle = theme.idText;
    ctx.fillText(`ID: ${idText}`, pillX + 26, y + 52);
  });

  ctx.textAlign = "center";
  ctx.font = "700 20px serif";
  ctx.fillStyle = theme.headerText;
  ctx.fillText("Meelad Fest 2k26", W / 2, cardY + cardH - 46);
  ctx.font = "400 14px sans-serif";
  ctx.fillStyle = theme.subText;
  ctx.fillText("Sep-05 · Saturday · Unnalu, Koyyur", W / 2, cardY + cardH - 22);
}

function wrapText(ctx, text, x, y, maxWidth, lineHeight) {
  const words = text.split(" ");
  const lines = [];
  let line = "";
  words.forEach((word) => {
    const test = line ? line + " " + word : word;
    if (ctx.measureText(test).width > maxWidth && line) {
      lines.push(line);
      line = word;
    } else {
      line = test;
    }
  });
  if (line) lines.push(line);
  lines.forEach((l, i) => ctx.fillText(l, x, y + i * lineHeight));
}

function ParticipantLookup({ students, competitions, results, groups }) {
  const [studentId, setStudentId] = useState("");
  const [searched, setSearched] = useState(false);
  const student = findStudentById(students, studentId.trim());
  const rows = searched ? findStudentResultsById(studentId.trim(), competitions, results) : [];

  function handleSearch(e) {
    e.preventDefault();
    setSearched(true);
  }

  return (
    <div className="mt-12 rounded-2xl border border-emerald-900/10 bg-white/80 p-6">
      <h2 className="font-display text-lg text-emerald-900">🔎 Participant Lookup</h2>
      <p className="mt-1 text-xs text-emerald-900/50">Enter a student ID to see which competitions they placed in.</p>
      <form onSubmit={handleSearch} className="mt-4 flex gap-2">
        <input value={studentId} onChange={(e) => { setStudentId(e.target.value); setSearched(false); }} placeholder="Student ID (e.g. K01)"
          className="flex-1 rounded-lg border border-emerald-900/15 px-3 py-2.5 text-sm outline-none focus:border-emerald-500" />
        <button type="submit" className="rounded-full bg-emerald-700 px-5 py-2.5 text-sm font-semibold text-white hover:bg-emerald-800">Search</button>
      </form>

      {searched && (
        <div className="mt-5">
          {!student ? (
            <p className="text-sm text-amber-700">No student found with that ID.</p>
          ) : (
            <>
              <p className="text-sm font-semibold text-emerald-900">{student.name} · {groupName(groups, student.groupId)} · ID: {student.studentId}</p>
              {rows.length === 0 ? (
                <p className="mt-2 text-sm text-emerald-900/50">No announced placements yet.</p>
              ) : (
                <ul className="mt-3 space-y-2">
                  {rows.map((row, i) => (
                    <li key={i} className="flex items-center justify-between rounded-xl border border-emerald-900/10 bg-white/60 p-3 text-sm">
                      <span>{row.competitionName}</span>
                      <span className="font-semibold">{row.medal} {row.place === "first" ? "1st" : row.place === "second" ? "2nd" : "3rd"}</span>
                    </li>
                  ))}
                </ul>
              )}
            </>
          )}
        </div>
      )}
    </div>
  );
}


